'use strict';
const E = window.DisabledAccessEngine;
const areas = E.datasets();
if(window.DisabledAccessDelhi)areas.unshift(E.validate(JSON.parse(JSON.stringify(window.DisabledAccessDelhi))));
const $ = id => document.getElementById(id);
const esc = text => String(text).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, baseline, result=null, after=false, selectedJourney, selectedBarrier=null, manualIds=[], manualView=false, manualPlan=null;
let noteStorageAvailable=true;
const money=value=>'₹'+Number(value).toLocaleString('en-IN');
function moneyLimit(){if(!$('use-money').checked)return null;const value=Number($('money-budget').value);if($('money-budget').value.trim()===''||!Number.isSafeInteger(value)||value<0)throw new Error('Enter a whole nonnegative money budget.');return value;}
function pending(r){return r.resolvesBarrierIds.some(id=>data.barriers.find(b=>b.id===id).status==='active');}
function clearPlans(){baseline=E.evaluate(data);result=null;after=false;manualView=false;manualIds=[];manualPlan=E.evaluate(data,[],baseline);}
try {const saved=JSON.parse(localStorage.getItem('disabledaccess-notes-v1')||'{}');for(const area of areas)for(const b of area.barriers){const note=saved[area.id]?.[b.id];if(note&&typeof note.title==='string'&&typeof note.description==='string'){b.title=note.title.slice(0,120);b.description=note.description.slice(0,1500);}}}catch{noteStorageAvailable=false;}
function loadArea(id) {
  data=areas.find(a=>a.id===id); baseline=E.evaluate(data); result=null;after=false;selectedBarrier=null;
  manualIds=[];manualView=false;manualPlan=E.evaluate(data,[],baseline);
  selectedJourney=data.id==='city'?'A1-F1':data.id==='teaching'?'J1':data.journeys[0].id;
  $('area').value=id;$('area-description').textContent=data.description;$('map-title').textContent=data.name;
  $('budget').max=data.maxRepairLimit;$('budget').value=data.defaultRepairLimit;$('budget-value').textContent=data.defaultRepairLimit;$('max-budget').textContent=data.maxRepairLimit+' repairs';
  $('money-budget').value=data.defaultMoneyBudget;$('use-money').checked=true;
  $('source-note').innerHTML=data.source?`<strong>Real street geometry · hypothetical accessibility scenario.</strong> © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors, ODbL</a>. Retrieved ${esc(data.source.retrieved)}. <a href="${esc(data.source.mapUrl)}" target="_blank" rel="noopener">View source map</a>. D1–D8 are selected map points, not named establishments. Roads are assumed bidirectional for this scenario; mapped roads do not establish usable sidewalks. Barriers and costs are invented for testing.`:'Fictional network and illustrative costs. No field conditions are asserted.';
  $('map-subtitle').textContent=data.source?'OSM geometry · local extract, not a navigation map':'Schematic network · not a surveyed map';
  $('journey').innerHTML=data.journeys.map(j=>`<option value="${esc(j.id)}">${esc(j.label)}</option>`).join('');
  render();
}
function active(){return after ? (manualView ? manualPlan : result?.recommended||baseline) : baseline;}
function render(){
  $('before').setAttribute('aria-pressed',String(!after));$('after').setAttribute('aria-pressed',String(after&&!manualView));$('after').disabled=!result;
  $('manual-view').setAttribute('aria-pressed',String(after&&manualView));
  $('journey').value=selectedJourney;
  renderMap();renderPlan();renderMetrics();renderMatrix();renderRoute();renderComparison();
}
function renderMap(){
  const plan=active(),usable=new Set(plan.usablePathIds),route=plan.journeyResults.find(j=>j.journeyId===selectedJourney),highlight=new Set(route?.pathIds||[]),nodes=new Map(data.nodes.map(n=>[n.id,n]));
  const repaired=new Set([...data.barriers.filter(b=>b.status==='resolved').map(b=>b.id),...data.repairs.filter(r=>plan.repairIds.includes(r.id)).flatMap(r=>r.resolvesBarrierIds)]);
  let svg='<svg viewBox="0 0 820 520" role="img" aria-label="Schematic area network. Textual routes and repair details are available beside the map.">';
  if(data.id==='city')for(const area of [...new Set(data.nodes.map(n=>n.area))]){const group=data.nodes.filter(n=>n.area===area),cx=group.reduce((s,n)=>s+n.x,0)/5,cy=group.reduce((s,n)=>s+n.y,0)/5;svg+=`<rect x="${cx-104}" y="${cy-88}" width="208" height="186" rx="24" fill="#edf3f2" stroke="#d9e6e3"/><text x="${cx}" y="${cy+120}" text-anchor="middle" class="district-label">${esc(area)}</text>`;}
  for(const p of data.paths){const a=nodes.get(p.from),b=nodes.get(p.to),geometry=p.geometry||[a,b];svg+=`<polyline points="${geometry.map(n=>`${n.x},${n.y}`).join(' ')}" class="path-line ${!usable.has(p.id)?'is-blocked':''} ${p.barrierIds.length&&usable.has(p.id)?'is-repaired':''} ${highlight.has(p.id)?'is-selected':''}"/>`;}
  if(data.source){const names=new Set();for(const p of data.paths){const name=p.streetNames?.find(n=>['Janpath','Outer Circle','Inner Circle','Middle Circle','Sansad Marg','Connaught Lane','Radial Road 1','Radial Road 2'].includes(n));if(!name||names.has(name)||!p.geometry||p.lengthMeters<25)continue;names.add(name);const point=p.geometry[Math.floor(p.geometry.length/2)];svg+=`<text x="${point.x+5}" y="${point.y-7}" class="street-label">${esc(name)}</text>`;}}
  for(const n of data.nodes)svg+=`<circle cx="${n.x}" cy="${n.y}" r="${n.kind==='junction'?(data.source?2:6):10}" class="map-node"/>${n.label?`<text x="${n.x}" y="${n.y+27}" text-anchor="middle" class="node-label">${esc(n.label)}</text>`:''}`;
  for(const barrier of data.barriers){const p=data.paths.find(p=>p.barrierIds.includes(barrier.id));if(!p)continue;const a=nodes.get(p.from),b=nodes.get(p.to),n=nodes.get(barrier.nodeId),cx=n?n.x:(a.x+b.x)/2,cy=n?n.y:(a.y+b.y)/2,id=barrier.id,fixed=repaired.has(id);svg+=`<g class="barrier-button" role="button" tabindex="0" data-barrier="${esc(id)}" aria-label="Inspect ${esc(barrier.title)}"><circle cx="${cx}" cy="${cy}" r="12" class="barrier-marker ${fixed?'repaired':''}"/><text x="${cx}" y="${cy+6}" text-anchor="middle" class="barrier-symbol">${fixed?'✓':'×'}</text></g>`;}
  $('map').innerHTML=svg+'</svg>';
  $('map-caption').textContent=after?`${manualView?'Your plan':'Recommended plan'} simulation · blue highlights the selected journey.`:'Current conditions · select a barrier marker to inspect it.';
  $('map').querySelectorAll('[data-barrier]').forEach(el=>{const inspect=()=>{selectedBarrier=el.dataset.barrier;renderPlan();};el.onclick=inspect;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect();}};});
}
function renderPlan(){
  if(selectedBarrier){
    const b=data.barriers.find(b=>b.id===selectedBarrier),r=data.repairs.find(r=>r.resolvesBarrierIds.includes(b.id));
    $('plan-content').innerHTML=`<p class="result-meta">SCENARIO LOCATION / ${esc(b.id)}</p><h2 class="barrier-title">${esc(b.title)}</h2><p class="secondary">${esc(b.description)}</p><p class="result-meta">${money(r.cost)} illustrative estimate · ${b.status==='resolved'?'Resolved in scenario':'Active barrier'}</p><details class="note-editor"><summary>Edit cost, status & notes</summary><form id="note-form"><label for="note-title">Barrier title</label><input id="note-title" maxlength="120" required value="${esc(b.title)}"><label for="repair-cost">Estimated repair cost (₹)</label><input id="repair-cost" type="number" min="0" max="100000000" step="1" required value="${r.cost}"><label for="barrier-status">Scenario status</label><select id="barrier-status"><option value="active" ${b.status==='active'?'selected':''}>Active barrier</option><option value="resolved" ${b.status==='resolved'?'selected':''}>Resolved in scenario</option></select><label for="path-condition">Underlying path conditions</label><select id="path-condition"><option value="compatible">Assume compatible for this scenario</option><option value="unknown">Unknown — exclude affected paths</option></select><label for="note-description">Notes</label><textarea id="note-description" maxlength="1500" rows="4">${esc(b.description)}</textarea><button class="back-button" type="submit">Save scenario change</button></form><p class="result-meta">Edits change the simulation, not verified ground truth. Unknown conditions stay excluded even after a barrier is resolved.</p></details><p id="note-feedback" role="status" class="result-meta"></p><button class="back-button" id="back-plan">Back to plan</button>`;
    $('path-condition').value=data.paths.some(p=>p.barrierIds.includes(b.id)&&p.fixedCompatibility==='unknown')?'unknown':'compatible';
    $('back-plan').onclick=()=>{selectedBarrier=null;renderPlan();};
    $('note-form').onsubmit=event=>{event.preventDefault();const title=$('note-title').value.trim(),cost=Number($('repair-cost').value),status=$('barrier-status').value,condition=$('path-condition').value;
      if(!title||$('repair-cost').value.trim()===''||!Number.isSafeInteger(cost)||cost<0||cost>100000000||!['active','resolved'].includes(status)||!['compatible','unknown'].includes(condition)){$('note-feedback').textContent='Enter a title, valid cost and scenario status.';return;}
      b.title=title.slice(0,120);b.description=$('note-description').value.trim().slice(0,1500);b.status=status;r.cost=cost;
      for(const p of data.paths.filter(p=>p.barrierIds.includes(b.id)))p.fixedCompatibility=condition;
      persistScenario();clearPlans();render();$('note-feedback').textContent=noteStorageAvailable?'Saved locally. Plans cleared and baseline recalculated.':'Updated for this session. Browser storage unavailable.';
    };return;
  }
  if(after&&manualView){const p=manualPlan;$('plan-content').innerHTML=`<p class="result-meta">YOUR REPAIR PLAN</p><div class="plan-count">+${p.newlyConnectedJourneyIds.length}</div><h2>journeys connected.</h2><p class="secondary">${p.repairIds.length} of ${$('budget').value} repairs selected.</p><ol class="repair-list">${p.repairIds.map((id,i)=>`<li><span class="number">${i+1}</span><span>${esc(data.repairs.find(r=>r.id===id).title)}</span></li>`).join('')}</ol><p class="result-meta">Choose repairs in the comparison section below. Run Find repair plan to compare against the optimizer.</p>`;return;}
  if(!result){$('plan-content').innerHTML='<div class="empty-symbol">⌘</div><h2>Where should<br>we start?</h2><p class="secondary">Choose a repair limit and optional money budget, then find the combination that reconnects the most tracked journeys.</p><p class="result-meta">Some barriers only make a difference when repaired together.</p>';return;}
  const p=result.recommended;
  $('plan-content').innerHTML=`<div class="plan-count">+${p.newlyConnectedJourneyIds.length}</div><h2>journeys connected.</h2><p class="secondary">${p.repairIds.length?`${p.repairIds.length} strategic repair${p.repairIds.length===1?'':'s'} in this plan.`:'No permitted repair plan improves connectivity.'}</p><ol class="repair-list">${p.repairIds.map((id,i)=>`<li><span class="number">${String(i+1).padStart(2,'0')}</span><span>${esc(data.repairs.find(r=>r.id===id).title)}</span></li>`).join('')}</ol><p class="result-meta">${money(p.totalCost)} estimated plan cost.<br>${result.evaluatedPlanCount} affordable combinations evaluated.<br>Each journey is a selected destination pair, not a measured trip.</p>`;
}
function renderMetrics(){const p=active(),total=data.journeys.length,disconnected=total-p.connectedCount;const cards=[['Connected pairs',`${p.connectedCount} <small>/ ${total}</small>`,after?'After simulated repairs':'Current recorded network',''],['Newly connected',`+${p.newlyConnectedJourneyIds.length}`,'Compared with current conditions','accent'],['Pairs disconnected',`${(100*disconnected/total).toFixed(1)}<small>%</small>`,`${disconnected} of ${total} tracked pairs`,''],['Repairs in view',String(p.repairIds.length),after?'Hypothetical interventions':'No repairs applied','']];$('metrics').innerHTML=cards.map(([label,value,hint,cls])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value ${cls}">${value}</div><div class="metric-hint">${hint}</div></div>`).join('');}
function renderMatrix(){
  const p=active(),results=new Map(p.journeyResults.map(j=>[j.journeyId,j])),newly=new Set(p.newlyConnectedJourneyIds);
  if(data.id!=='city')$('matrix').innerHTML=`<div class="simple-pairs ${data.source?'delhi-pairs':''}">${data.journeys.map(j=>`<button class="pair-button ${results.get(j.id).reachable?'connected':''}" data-journey="${j.id}"><span>${esc(j.label)}</span><span>${results.get(j.id).reachable?'✓':'×'}</span></button>`).join('')}</div>`;
  else {let content='<span></span>'+data.nodes.map(n=>`<span class="matrix-axis">${esc(n.id)}</span>`).join('');for(let i=0;i<data.nodes.length;i++){content+=`<span class="matrix-axis">${data.nodes[i].id}</span>`;for(let k=0;k<data.nodes.length;k++){if(k<=i){content+='<span class="matrix-blank" aria-hidden="true"></span>';continue;}const id=`${data.nodes[i].id}-${data.nodes[k].id}`,r=results.get(id);content+=`<button class="matrix-cell ${r.reachable?'connected':''} ${newly.has(id)?'new':''} ${id===selectedJourney?'selected':''}" data-journey="${id}" aria-label="${id}: ${r.reachable?'connected':'disconnected'}" title="${id}: ${r.reachable?'connected':'disconnected'}">${r.reachable?'✓':'×'}</button>`;}}$('matrix').innerHTML=`<div class="matrix-grid" style="grid-template-columns:20px repeat(30,minmax(8px,1fr))">${content}</div>`;}
  $('matrix').querySelectorAll('[data-journey]').forEach(button=>button.onclick=()=>{selectedJourney=button.dataset.journey;render();$('journey').focus();});
}
function renderRoute(){const p=active(),j=p.journeyResults.find(j=>j.journeyId===selectedJourney),old=baseline.journeyResults.find(j=>j.journeyId===selectedJourney);if(!j)return;let explanation='';if(after&&j.reachable&&!old.reachable){const necessary=p.repairIds.filter(id=>!E.evaluate(data,p.repairIds.filter(r=>r!==id)).journeyResults.find(x=>x.journeyId===j.journeyId).reachable);explanation=`${necessary.length} of the selected repairs ${necessary.length===1?'is':'are'} individually necessary for this connection: ${necessary.map(esc).join(', ')}.`;}
  const selected=data.journeys.find(x=>x.id===selectedJourney),locations=data.source?`<p>${[selected.origin,selected.destination].map(id=>{const n=data.nodes.find(n=>n.id===id);return esc(n.label+': '+n.description);}).join('<br>')}</p>`:'';
  $('route-details').innerHTML=locations+`<span class="route-status ${j.reachable?'connected':''}">${j.reachable?'✓ Connected in this view':'× No compatible connection'}</span>${j.reachable?`<div class="route-distance">${j.distanceMeters} <small>m</small></div><p class="route-path">${j.nodeIds.map(id=>data.nodes.find(n=>n.id===id).label).filter(Boolean).map(esc).join(' → ')}</p><p>${explanation||(data.source?'Geometry-derived distance; path compatibility and barriers are scenario assumptions.':'This journey is connected in this scenario. Distances are illustrative.')}</p>`:'<p>The recorded network does not provide a complete compatible route for this pair. Try a repair plan, then compare the result.</p>'}`;
}
$('area').onchange=e=>loadArea(e.target.value);
$('budget').oninput=()=>{$('budget-value').textContent=$('budget').value;result=null;after=false;manualView=false;manualIds=[];manualPlan=E.evaluate(data,[],baseline);selectedBarrier=null;render();$('status').textContent='Repair limit changed. Your previous selections were cleared.';};
$('optimize').onclick=()=>{const button=$('optimize');button.disabled=true;button.textContent='Evaluating repairs…';$('status').textContent='Calculating repair combinations.';setTimeout(()=>{try{result=E.recommend(data,Number($('budget').value),moneyLimit());after=true;manualView=false;selectedBarrier=null;render();$('status').textContent=`${result.recommended.newlyConnectedJourneyIds.length} pairs newly connected with ${result.recommended.repairIds.length} repairs.`;}catch(error){$('status').textContent=error.message;$('plan-content').textContent=error.message;}finally{button.disabled=false;button.innerHTML='Find repair plan <span aria-hidden="true">✦</span>'; }},30);};
$('reset').onclick=()=>loadArea(data.id);
$('before').onclick=()=>{after=false;render();};$('after').onclick=()=>{after=true;manualView=false;selectedBarrier=null;render();};
$('manual-view').onclick=()=>{after=true;manualView=true;selectedBarrier=null;render();};
$('journey').onchange=e=>{selectedJourney=e.target.value;render();};
function toggleManual(id,checked){
  if(!data.repairs.some(r=>r.id===id))throw new Error('Unknown repair');
  if(checked&&!manualIds.includes(id)){let cap;try{cap=moneyLimit();}catch(error){$('status').textContent=error.message;return;}const repair=data.repairs.find(r=>r.id===id);if(!pending(repair)||manualIds.length>=Number($('budget').value)||(cap!==null&&manualPlan.totalCost+repair.cost>cap)){$('status').textContent='Repair limit or money budget reached, or repair is already resolved.';renderComparison();return;}manualIds.push(id);}
  if(!checked)manualIds=manualIds.filter(r=>r!==id);
  manualPlan=E.evaluate(data,manualIds,baseline);after=true;manualView=true;selectedBarrier=null;render();
  $('status').textContent=`Your ${manualIds.length} repairs reconnect ${manualPlan.newlyConnectedJourneyIds.length} pairs.`;
  const input=$('repair-choices').querySelector(`[data-repair="${id}"]`);if(input)input.focus();
}
function renderComparison(){
  const limit=Number($('budget').value),full=manualIds.length>=limit;let cap=null;try{cap=moneyLimit();}catch{}
  $('selection-count').textContent=manualIds.length+' / '+limit+' repairs selected · '+money(manualPlan.totalCost)+(cap!==null?' / '+money(cap):'');
  $('repair-choices').innerHTML=data.repairs.map(r=>{const picked=manualIds.includes(r.id),done=!pending(r),disabled=!picked&&(full||done||(cap!==null&&manualPlan.totalCost+r.cost>cap));return `<label class="repair-choice ${picked?'picked':''}"><input type="checkbox" data-repair="${esc(r.id)}" ${picked?'checked':''} ${disabled?'disabled':''}><span>${esc(r.title)}<small>${money(r.cost)} · ${done?'Already resolved':esc(r.id)}</small></span></label>`;}).join('');
  $('repair-choices').querySelectorAll('[data-repair]').forEach(input=>input.onchange=()=>toggleManual(input.dataset.repair,input.checked));
  const yours=manualPlan.newlyConnectedJourneyIds.length,opt=result?.recommended.newlyConnectedJourneyIds.length;
  $('comparison-result').innerHTML=`<div class="comparison-score"><span>Your plan<strong>+${yours}</strong><small>${manualIds.length} repairs · ${money(manualPlan.totalCost)}</small></span><span>Recommended<strong>${opt===undefined?'—':'+'+opt}</strong><small>${result?result.recommended.repairIds.length+' repairs · '+money(result.recommended.totalCost):'Not calculated yet'}</small></span></div><p>${opt===undefined?'Run Find repair plan to compare under the same constraints.':opt===yours?'Your plan matches the best connectivity gain under these constraints.':'The recommended plan connects '+(opt-yours)+' more pairs under the same limits.'}</p><p class="secondary">Illustrative estimates, not quotations. When a money budget is enabled, ties prefer lower total cost, then fewer repairs and shorter routes.</p>`;
}
$('clear-manual').onclick=()=>{manualIds=[];manualPlan=E.evaluate(data,[],baseline);after=true;manualView=true;selectedBarrier=null;render();};
function persistScenario(){try{const saved={};for(const area of areas)saved[area.id]={barriers:area.barriers.map(b=>({id:b.id,title:b.title,description:b.description,status:b.status})),repairs:area.repairs.map(r=>({id:r.id,cost:r.cost})),paths:area.paths.map(p=>({id:p.id,fixedCompatibility:p.fixedCompatibility}))};localStorage.setItem('disabledaccess-scenarios-v3',JSON.stringify(saved));noteStorageAvailable=true;}catch{noteStorageAvailable=false;}}
try{const saved=JSON.parse(localStorage.getItem('disabledaccess-scenarios-v3')||'{}');for(const area of areas){const s=saved[area.id];if(!s)continue;for(const b of area.barriers){const v=s.barriers?.find(x=>x.id===b.id);if(v&&typeof v.title==='string'&&typeof v.description==='string'&&['active','resolved'].includes(v.status)){b.title=v.title.slice(0,120);b.description=v.description.slice(0,1500);b.status=v.status;}}for(const r of area.repairs){const v=s.repairs?.find(x=>x.id===r.id);if(v&&Number.isSafeInteger(v.cost)&&v.cost>=0&&v.cost<=100000000)r.cost=v.cost;}for(const p of area.paths){const v=s.paths?.find(x=>x.id===p.id);if(v&&['compatible','unknown'].includes(v.fixedCompatibility))p.fixedCompatibility=v.fixedCompatibility;}}}catch{noteStorageAvailable=false;}
$('use-money').onchange=$('money-budget').oninput=()=>{clearPlans();selectedBarrier=null;render();};
$('restore-sample').onclick=()=>{const id=data.id,fresh=id==='delhi'?JSON.parse(JSON.stringify(window.DisabledAccessDelhi)):E.datasets().find(a=>a.id===id);areas[areas.findIndex(a=>a.id===id)]=fresh;persistScenario();loadArea(id);$('status').textContent='Original sample restored for this area.';};
loadArea(areas.some(a=>a.id==='delhi')?'delhi':'city');

